state.originalResume=state.originalResume||{text:'',files:[],updatedAt:null};
const masterText=document.querySelector('#masterResumeText'),masterPicker=document.querySelector('#masterResumeInput'),masterDrop=document.querySelector('#masterResumeDropzone'),masterStatus=document.querySelector('#masterImportStatus'),masterState=document.querySelector('#masterResumeState');
const saveMasterChoice=document.querySelector('#saveMasterToLibrary');
masterText.value=state.originalResume.text||'';
function updateMasterState(){const ready=!!state.originalResume.text.trim();masterState.textContent=ready?`已保存原版 · ${state.originalResume.text.length} 字`:'尚未导入';masterState.classList.toggle('ready',ready)}
masterText.addEventListener('input',()=>{state.originalResume.text=masterText.value;state.originalResume.updatedAt=new Date().toISOString();save();updateMasterState()});
function saveMasterToCurrentLibrary(){const text=state.originalResume.text.trim();if(!text)return;const id='master-source-'+PROFILE_ID,title=`${state.profile.name||'当前档案'} · 原始简历`,html=textToResumeHtml(text,title),record={id,title,company:'',jobTitle:'原始简历',category:'原始简历',createdAt:new Date().toISOString(),html,text,job:{}};const at=state.resumes.findIndex(x=>x.id===id);if(at>=0)state.resumes[at]={...state.resumes[at],...record};else state.resumes.unshift(record);state.activeResumeId=id;save();renderLibrary()}
async function importMasterFiles(files){const allowed=files.filter(f=>/\.(pdf|docx|txt|png|jpe?g|webp)$/i.test(f.name));if(!allowed.length)return toast('请上传 PDF、DOCX、TXT 或简历图片');masterStatus.textContent=`正在完整扫描 ${allowed.length} 个原版文件…`;const texts=[];for(let i=0;i<allowed.length;i++){const file=allowed[i];try{const value=await extractUploadedFile(file,{label:`第 ${i+1} 个文件`});if(!value.trim())throw new Error('没有识别到文字');texts.push(value);masterStatus.textContent=`已读取 ${i+1}/${allowed.length} 个文件`}catch(e){state.logs.push({time:new Date().toISOString(),event:'master_import_error',file:file.name,message:e.message});masterStatus.textContent=`${file.name}：${e.message}`}}if(!texts.length){save();return masterStatus.textContent='原版简历读取失败，请下载错误报告'}state.originalResume.text=texts.join('\n\n');state.originalResume.files=allowed.map(x=>x.name);state.originalResume.updatedAt=new Date().toISOString();masterText.value=state.originalResume.text;save();updateMasterState();if(saveMasterChoice.checked)saveMasterToCurrentLibrary();masterStatus.textContent=saveMasterChoice.checked?'原版全文已存入当前人员简历库，Codex 正在拆分事实…':'原版全文已保存在当前档案，Codex 正在拆分事实…';await syncFactsFromResumes([{title:'通用原版简历',text:state.originalResume.text}],true,true);if(saveMasterChoice.checked)saveMasterToCurrentLibrary();masterStatus.textContent=`原版全文已保存，共识别 ${state.profile.experiences.length} 份经历${saveMasterChoice.checked?'，并已另存到简历库':''}；请检查后手动修正`}
async function parseMaster(){state.originalResume.text=masterText.value.trim();if(!state.originalResume.text)return toast('请先上传、粘贴或手动输入通用原版简历');save();updateMasterState();if(saveMasterChoice.checked)saveMasterToCurrentLibrary();masterStatus.textContent=saveMasterChoice.checked?'原版全文已存入当前人员简历库，Codex 正在拆分事实…':'原版全文已保存在当前档案，Codex 正在拆分事实…';await syncFactsFromResumes([{title:'通用原版简历',text:state.originalResume.text}],false,true);if(saveMasterChoice.checked)saveMasterToCurrentLibrary();masterStatus.textContent=`已识别 ${state.profile.experiences.length} 份独立经历${saveMasterChoice.checked?'，并已另存到简历库':''}`}
masterDrop.onclick=()=>masterPicker.click();masterDrop.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();masterPicker.click()}};masterPicker.onchange=()=>{importMasterFiles([...masterPicker.files]);masterPicker.value=''};['dragenter','dragover'].forEach(t=>masterDrop.addEventListener(t,e=>{e.preventDefault();masterDrop.classList.add('dragging')}));['dragleave','dragend'].forEach(t=>masterDrop.addEventListener(t,e=>{e.preventDefault();masterDrop.classList.remove('dragging')}));masterDrop.addEventListener('drop',e=>{e.preventDefault();masterDrop.classList.remove('dragging');importMasterFiles([...(e.dataTransfer?.files||[])])});document.querySelector('#parseMasterResume').onclick=parseMaster;updateMasterState();
document.querySelector('#rescanExperiences').onclick=async()=>{if(!state.originalResume.text.trim())return toast('请先导入通用原版简历');if(!confirm('将以当前原版简历重新建立自我评价、教育、技能和经历，照片与自定义栏目会保留。确定继续吗？'))return;await parseMaster();toast(`重新扫描完成，共更新 ${state.profile.experiences.length} 份经历`)};
